core_reasoning_1:
\section*{Claim}
For functions satisfying the premises below, the differential form of Chandrasekhar's isotropic \(H\)-function is
\[
\frac{\partial H(\mu,\omega)}{\partial \mu}
-\left(\frac{1}{2\mu}-\frac{\omega}{2(1+\mu)}\right)H^2(\mu,\omega)
=-\frac{1}{2\mu},
\qquad 0<\mu\le 1,\quad 0<\omega\le 1.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &0<\mu\le 1,\quad 0<\omega\le 1,\quad H(\mu,\omega)\ne 0.\\
\text{(P2)}\quad &Z_0(\mu,\omega)=\ln\left(1+\frac{1}{\mu}\right)+\frac{\omega}{2}Z_1(\mu,\omega).\\
\text{(P3)}\quad &\frac{\partial Z_1(\mu,\omega)}{\partial\mu}=-\frac{1}{2}Z_0^2(\mu,\omega).\\
\text{(P4)}\quad &Z_0(\mu,\omega)=\frac{2}{\omega\mu}\left(1-\frac{1}{H(\mu,\omega)}\right).\\
\text{(P5)}\quad &\frac{d}{d\mu}\ln\left(1+\frac{1}{\mu}\right)=-\frac{1}{\mu(1+\mu)}.\\
\text{(P6)}\quad &H_\mu(\mu,\omega):=\frac{\partial H(\mu,\omega)}{\partial\mu}.
\end{aligned}
\]

\section*{Derivation}
Differentiate \(Z_0\) using (P2):
\begin{align}
\frac{\partial Z_0}{\partial\mu}
&=\frac{d}{d\mu}\ln\left(1+\frac{1}{\mu}\right)+\frac{\omega}{2}\frac{\partial Z_1}{\partial\mu} &&\text{differentiate (P2)}\\
&=-\frac{1}{\mu(1+\mu)}+\frac{\omega}{2}\left(-\frac{1}{2}Z_0^2\right) &&\text{by (P3) and (P5)}\\
&=-\frac{1}{\mu(1+\mu)}-\frac{\omega}{4}Z_0^2. &&\text{simplify}
\end{align}
Thus
\begin{align}
\frac{\partial Z_0}{\partial\mu}+\frac{\omega}{4}Z_0^2
&=-\frac{1}{\mu(1+\mu)}. &&\text{move the quadratic term}
\end{align}
Define
\[
Q(\mu,\omega):=1-\frac{1}{H(\mu,\omega)}.
\]
Then (P4) gives \(Z_0=2Q/(\omega\mu)\). Compute the two terms in the Riccati equation:
\begin{align}
\frac{\partial Q}{\partial\mu}
&=\frac{H_\mu}{H^2} &&\text{differentiate }Q=1-H^{-1}\text{ using (P6)}\\
\frac{\partial Z_0}{\partial\mu}
&=\frac{2}{\omega}\frac{\partial}{\partial\mu}\left(\frac{Q}{\mu}\right) &&\text{use }Z_0=\frac{2Q}{\omega\mu}\\
&=\frac{2}{\omega}\left(\frac{H_\mu}{\mu H^2}-\frac{Q}{\mu^2}\right) &&\text{quotient rule and previous line}\\
\frac{\omega}{4}Z_0^2
&=\frac{\omega}{4}\left(\frac{2Q}{\omega\mu}\right)^2 &&\text{substitute }Z_0\\
&=\frac{Q^2}{\omega\mu^2}. &&\text{simplify}
\end{align}
Substitute these expressions into the Riccati equation:
\begin{align}
\frac{2}{\omega}\left(\frac{H_\mu}{\mu H^2}-\frac{Q}{\mu^2}\right)
+\frac{Q^2}{\omega\mu^2}
&=-\frac{1}{\mu(1+\mu)} &&\text{substitution}\\
H_\mu-\frac{H^2Q}{\mu}+\frac{H^2Q^2}{2\mu}
&=-\frac{\omega H^2}{2(1+\mu)} &&\text{multiply by }\frac{\omega\mu H^2}{2}\\
H_\mu-\frac{H(H-1)}{\mu}+\frac{(H-1)^2}{2\mu}
&=-\frac{\omega H^2}{2(1+\mu)} &&\text{use }HQ=H-1\\
H_\mu
&=\frac{H(H-1)}{\mu}-\frac{(H-1)^2}{2\mu}-\frac{\omega H^2}{2(1+\mu)} &&\text{solve for }H_\mu\\
&=\frac{2H(H-1)-(H-1)^2}{2\mu}-\frac{\omega H^2}{2(1+\mu)} &&\text{common denominator}\\
&=\frac{H^2-1}{2\mu}-\frac{\omega H^2}{2(1+\mu)} &&\text{expand and combine}\\
H_\mu-\left(\frac{1}{2\mu}-\frac{\omega}{2(1+\mu)}\right)H^2
&=-\frac{1}{2\mu}. &&\text{collect }H^2\text{ terms}
\end{align}

\section*{Final Result}
\[
\boxed{
\frac{\partial H(\mu,\omega)}{\partial \mu}
-\left(\frac{1}{2\mu}-\frac{\omega}{2(1+\mu)}\right)H^2(\mu,\omega)
=-\frac{1}{2\mu}
}
\]
\hfill$\blacksquare$

core_reasoning_2:
\section*{Claim}
As formal Laurent identities in \(\mu^{-1}\), the moment coefficients satisfy
\[
4(n+1)\alpha_n(\omega)=4+\omega\sum_{m=0}^{n}\alpha_m(\omega)\alpha_{n-m}(\omega),
\qquad n=0,1,2,\ldots,
\]
and the first two moment functions are
\[
\alpha_0(\omega)=
\begin{cases}
1, & \omega=0,\\
\dfrac{2}{\omega}\left(1-\sqrt{1-\omega}\right), & 0<\omega\le 1,
\end{cases}
\qquad
\alpha_1(\omega)=\frac{1}{1+\sqrt{1-\omega}},
\qquad 0\le \omega\le 1.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &0\le \omega\le 1,\quad n\in\{0,1,2,\ldots\},\quad \mu>0,\\
&\text{and all series manipulations are formal Laurent manipulations in }\mu^{-1}.\\
\text{(P2)}\quad &Z_0(\mu,\omega)=\sum_{n=0}^{\infty}(-1)^n\alpha_n(\omega)\mu^{-n-1}.\\
\text{(P3)}\quad &\frac{\partial Z_0(\mu,\omega)}{\partial\mu}+\frac{\omega}{4}Z_0^2(\mu,\omega)
=\frac{d}{d\mu}\ln\left(1+\frac{1}{\mu}\right).\\
\text{(P4)}\quad &\frac{d}{d\mu}\ln\left(1+\frac{1}{\mu}\right)
=\sum_{n=0}^{\infty}(-1)^{n+1}\mu^{-n-2}.\\
\text{(P5)}\quad &\left(\sum_{n=0}^{\infty}a_nx^n\right)
\left(\sum_{n=0}^{\infty}b_nx^n\right)
=\sum_{n=0}^{\infty}\left(\sum_{m=0}^{n}a_mb_{n-m}\right)x^n.\\
\text{(P6)}\quad &\sum_{n=0}^{\infty}c_nx^n=\sum_{n=0}^{\infty}d_nx^n
\text{ as formal series }\Longrightarrow c_n=d_n\text{ for every }n.\\
\text{(P7)}\quad &\alpha_0(0)=1.
\end{aligned}
\]

\section*{Derivation}
Differentiate the formal expansion of \(Z_0\):
\begin{align}
\frac{\partial Z_0}{\partial\mu}
&=\frac{\partial}{\partial\mu}\sum_{n=0}^{\infty}(-1)^n\alpha_n\mu^{-n-1} &&\text{by (P2)}\\
&=\sum_{n=0}^{\infty}(-1)^n\alpha_n(-n-1)\mu^{-n-2} &&\text{termwise formal differentiation}\\
&=\sum_{n=0}^{\infty}(-1)^{n+1}(n+1)\alpha_n\mu^{-n-2}. &&\text{sign rearrangement}
\end{align}
Square the formal expansion of \(Z_0\):
\begin{align}
Z_0^2
&=\left(\sum_{n=0}^{\infty}(-1)^n\alpha_n\mu^{-n-1}\right)^2 &&\text{by (P2)}\\
&=\sum_{n=0}^{\infty}(-1)^n
\left(\sum_{m=0}^{n}\alpha_m\alpha_{n-m}\right)\mu^{-n-2} &&\text{by (P5)}.
\end{align}
Substitute these expressions and (P4) into (P3):
\begin{align}
\sum_{n=0}^{\infty}(-1)^{n+1}(n+1)\alpha_n\mu^{-n-2}
+\frac{\omega}{4}\sum_{n=0}^{\infty}(-1)^n
\left(\sum_{m=0}^{n}\alpha_m\alpha_{n-m}\right)\mu^{-n-2}
&=\sum_{n=0}^{\infty}(-1)^{n+1}\mu^{-n-2}. &&\text{substitution}
\end{align}
Equate the coefficient of \(\mu^{-n-2}\):
\begin{align}
(-1)^{n+1}(n+1)\alpha_n
+\frac{\omega}{4}(-1)^n\sum_{m=0}^{n}\alpha_m\alpha_{n-m}
&=(-1)^{n+1} &&\text{by (P6)}\\
(n+1)\alpha_n-\frac{\omega}{4}\sum_{m=0}^{n}\alpha_m\alpha_{n-m}
&=1 &&\text{multiply by }(-1)^{n+1}\\
4(n+1)\alpha_n
&=4+\omega\sum_{m=0}^{n}\alpha_m\alpha_{n-m}. &&\text{multiply by }4
\end{align}
For \(n=0\), this recurrence gives
\begin{align}
4\alpha_0&=4+\omega\alpha_0^2 &&\text{set }n=0\\
\omega\alpha_0^2-4\alpha_0+4&=0. &&\text{move all terms left}
\end{align}
For \(0<\omega\le 1\), solve the quadratic:
\begin{align}
\alpha_0
&=\frac{4\pm\sqrt{16-16\omega}}{2\omega} &&\text{quadratic formula}\\
&=\frac{2}{\omega}\left(1\pm\sqrt{1-\omega}\right). &&\text{simplify}
\end{align}
The minus branch is the unique branch compatible with \(\alpha_0(0)=1\):
\begin{align}
\frac{2}{\omega}\left(1-\sqrt{1-\omega}\right)
&=\frac{2}{1+\sqrt{1-\omega}} &&\text{rationalize numerator}\\
\lim_{\omega\downarrow 0}\frac{2}{1+\sqrt{1-\omega}}&=1 &&\text{evaluate}\\
\lim_{\omega\downarrow 0}\frac{2}{\omega}\left(1+\sqrt{1-\omega}\right)&=+\infty. &&\text{plus branch}
\end{align}
Hence
\begin{align}
\alpha_0(\omega)&=
\begin{cases}
1, & \omega=0,\\
\dfrac{2}{\omega}\left(1-\sqrt{1-\omega}\right), & 0<\omega\le 1.
\end{cases} &&\text{by (P7) and branch compatibility}
\end{align}
For \(n=1\), the recurrence gives
\begin{align}
8\alpha_1&=4+\omega(\alpha_0\alpha_1+\alpha_1\alpha_0) &&\text{set }n=1\\
(8-2\omega\alpha_0)\alpha_1&=4 &&\text{collect }\alpha_1\\
\alpha_1&=\frac{4}{8-2\omega\alpha_0}. &&\text{divide}
\end{align}
Let \(s:=\sqrt{1-\omega}\). For \(0<\omega\le 1\), \(\omega=1-s^2\) and \(\alpha_0=2/(1+s)\), so
\begin{align}
8-2\omega\alpha_0
&=8-2(1-s^2)\frac{2}{1+s} &&\text{substitute}\\
&=8-4(1-s) &&\text{cancel }1+s\\
&=4(1+s). &&\text{simplify}
\end{align}
Therefore
\begin{align}
\alpha_1&=\frac{4}{4(1+s)} &&\text{substitute the denominator}\\
&=\frac{1}{1+\sqrt{1-\omega}}. &&\text{replace }s
\end{align}
At \(\omega=0\), the same expression gives \(\alpha_1(0)=1/2\), which also agrees with \(8\alpha_1=4\) from the recurrence at \(\omega=0\).

\section*{Final Result}
\[
\boxed{
\begin{gathered}
4(n+1)\alpha_n(\omega)=4+\omega\sum_{m=0}^{n}\alpha_m(\omega)\alpha_{n-m}(\omega),\quad n=0,1,2,\ldots,\\
\alpha_0(\omega)=
\begin{cases}
1, & \omega=0,\\
\dfrac{2}{\omega}\left(1-\sqrt{1-\omega}\right), & 0<\omega\le 1,
\end{cases}
\qquad
\alpha_1(\omega)=\dfrac{1}{1+\sqrt{1-\omega}}.
\end{gathered}
}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
For \(0<\mu\le 1\) and \(0<\omega\le 1\), the substitution
\[
Z_0(\mu,\omega)=\frac{4}{\omega G(\mu,\omega)}\frac{\partial G(\mu,\omega)}{\partial\mu}
\]
transforms
\[
\frac{\partial Z_0}{\partial\mu}+\frac{\omega}{4}Z_0^2=-\frac{1}{\mu(1+\mu)}
\]
into
\[
\frac{\partial^2G(\mu,\omega)}{\partial\mu^2}
+\frac{\omega}{4\mu(1+\mu)}G(\mu,\omega)=0.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &0<\mu\le 1,\quad 0<\omega\le 1,
\quad G(\mu,\omega)\ne 0.\\
\text{(P2)}\quad &G_\mu(\mu,\omega):=\frac{\partial G(\mu,\omega)}{\partial\mu},
\quad
G_{\mu\mu}(\mu,\omega):=\frac{\partial^2G(\mu,\omega)}{\partial\mu^2}.\\
\text{(P3)}\quad &Z_0(\mu,\omega)=\frac{4}{\omega}\frac{G_\mu(\mu,\omega)}{G(\mu,\omega)}.\\
\text{(P4)}\quad &\frac{\partial Z_0(\mu,\omega)}{\partial\mu}
+\frac{\omega}{4}Z_0^2(\mu,\omega)
=-\frac{1}{\mu(1+\mu)}.\\
\text{(P5)}\quad &\frac{\partial}{\partial\mu}\left(\frac{G_\mu}{G}\right)
=\frac{G_{\mu\mu}G-G_\mu^2}{G^2}.\\
\text{(P6)}\quad &\frac{G_{\mu\mu}G-G_\mu^2}{G^2}
=\frac{G_{\mu\mu}}{G}-\left(\frac{G_\mu}{G}\right)^2.
\end{aligned}
\]

\section*{Derivation}
Compute \(\partial Z_0/\partial\mu\):
\begin{align}
\frac{\partial Z_0}{\partial\mu}
&=\frac{\partial}{\partial\mu}\left(\frac{4}{\omega}\frac{G_\mu}{G}\right) &&\text{by (P3)}\\
&=\frac{4}{\omega}\frac{\partial}{\partial\mu}\left(\frac{G_\mu}{G}\right) &&\text{constant factor}\\
&=\frac{4}{\omega}\frac{G_{\mu\mu}G-G_\mu^2}{G^2} &&\text{by (P5)}\\
&=\frac{4}{\omega}\left(\frac{G_{\mu\mu}}{G}-\left(\frac{G_\mu}{G}\right)^2\right). &&\text{by (P6)}
\end{align}
Compute the quadratic term:
\begin{align}
\frac{\omega}{4}Z_0^2
&=\frac{\omega}{4}\left(\frac{4}{\omega}\frac{G_\mu}{G}\right)^2 &&\text{by (P3)}\\
&=\frac{4}{\omega}\left(\frac{G_\mu}{G}\right)^2. &&\text{simplify}
\end{align}
Substitute into (P4):
\begin{align}
\frac{4}{\omega}\left(\frac{G_{\mu\mu}}{G}-\left(\frac{G_\mu}{G}\right)^2\right)
+\frac{4}{\omega}\left(\frac{G_\mu}{G}\right)^2
&=-\frac{1}{\mu(1+\mu)} &&\text{substitution}\\
\frac{4}{\omega}\frac{G_{\mu\mu}}{G}
&=-\frac{1}{\mu(1+\mu)} &&\text{cancel equal opposite terms}\\
G_{\mu\mu}
&=-\frac{\omega}{4\mu(1+\mu)}G &&\text{multiply by }\frac{\omega G}{4}\\
G_{\mu\mu}+\frac{\omega}{4\mu(1+\mu)}G&=0. &&\text{move all terms left}
\end{align}

\section*{Final Result}
\[
\boxed{
\frac{\partial^2G(\mu,\omega)}{\partial\mu^2}
+\frac{\omega}{4\mu(1+\mu)}G(\mu,\omega)=0
}
\]
\hfill$\blacksquare$

core_reasoning_4:
\section*{Claim}
Let \(0<\mu\le 1\), \(0<\omega\le 1\), and \(s:=\sqrt{1-\omega}\). If
\[
G(\mu,\omega):=\mu^{-\frac{1}{2}-\frac{s}{2}}(1+\mu)
{}_2F_1\left(\frac{3}{2}+\frac{s}{2},\frac{1}{2}+\frac{s}{2};1+s;-\frac{1}{\mu}\right),
\]
then the exact \(H\)-function represented by the paper's variables is
\[
H(\mu,\omega)=\frac{G(\mu,\omega)}{G(\mu,\omega)-2\mu G_\mu(\mu,\omega)}.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &0<\mu\le 1,
\quad 0<\omega\le 1,
\quad s:=\sqrt{1-\omega}.\\
\text{(P2)}\quad &a:=\frac{3}{2}+\frac{s}{2},
\quad b:=\frac{1}{2}+\frac{s}{2},
\quad c:=1+s,
\quad z:=-\frac{1}{\mu}.\\
\text{(P3)}\quad &\mathcal F_{a,b,c}(z):={}_2F_1(a,b;c;z),\\
&\text{where }\mathcal F_{a,b,c}\text{ is a differentiable branch satisfying}\\
&z(1-z)\mathcal F_{a,b,c}''(z)+\{c-(a+b+1)z\}\mathcal F_{a,b,c}'(z)-ab\mathcal F_{a,b,c}(z)=0.\\
\text{(P4)}\quad &G(\mu,\omega):=\mu^{-\frac{1}{2}-\frac{s}{2}}(1+\mu)\mathcal F_{a,b,c}\left(-\frac{1}{\mu}\right).\\
\text{(P5)}\quad &G_\mu(\mu,\omega):=\frac{\partial G(\mu,\omega)}{\partial\mu},
\quad G(\mu,\omega)\ne 0,
\quad G(\mu,\omega)-2\mu G_\mu(\mu,\omega)\ne 0.\\
\text{(P6)}\quad &Z_0(\mu,\omega)=\frac{4G_\mu(\mu,\omega)}{\omega G(\mu,\omega)}.\\
\text{(P7)}\quad &Z_0(\mu,\omega)=\frac{2}{\omega\mu}\left(1-\frac{1}{H(\mu,\omega)}\right).
\end{aligned}
\]

\section*{Derivation}
Equate the two formulas for \(Z_0\):
\begin{align}
\frac{2}{\omega\mu}\left(1-\frac{1}{H}\right)
&=\frac{4G_\mu}{\omega G} &&\text{by (P6) and (P7)}\\
1-\frac{1}{H}
&=\frac{\omega\mu}{2}\frac{4G_\mu}{\omega G} &&\text{multiply by }\frac{\omega\mu}{2}\\
1-\frac{1}{H}
&=\frac{2\mu G_\mu}{G} &&\text{cancel }\omega\\
\frac{1}{H}
&=1-\frac{2\mu G_\mu}{G} &&\text{solve for }H^{-1}\\
\frac{1}{H}
&=\frac{G-2\mu G_\mu}{G} &&\text{common denominator}\\
H&=\frac{G}{G-2\mu G_\mu}. &&\text{invert using (P5)}
\end{align}
Now substitute the definitions of \(s,a,b,c\) and \(\mathcal F\) into \(G\):
\begin{align}
G(\mu,\omega)
&=\mu^{-\frac{1}{2}-\frac{s}{2}}(1+\mu)\mathcal F_{a,b,c}\left(-\frac{1}{\mu}\right) &&\text{by (P4)}\\
&=\mu^{-\frac{1}{2}-\frac{\sqrt{1-\omega}}{2}}(1+\mu)
{}_2F_1\left(\frac{3}{2}+\frac{\sqrt{1-\omega}}{2},\frac{1}{2}+\frac{\sqrt{1-\omega}}{2};1+\sqrt{1-\omega};-\frac{1}{\mu}\right). &&\text{by (P1)--(P3)}
\end{align}

\section*{Final Result}
\[
\boxed{
\begin{gathered}
H(\mu,\omega)=\dfrac{G(\mu,\omega)}{G(\mu,\omega)-2\mu\,\dfrac{\partial G(\mu,\omega)}{\partial\mu}},\\
G(\mu,\omega):=\mu^{-\frac{1}{2}-\frac{\sqrt{1-\omega}}{2}}(1+\mu)
{}_2F_1\left(\frac{3}{2}+\frac{\sqrt{1-\omega}}{2},\frac{1}{2}+\frac{\sqrt{1-\omega}}{2};1+\sqrt{1-\omega};-\frac{1}{\mu}\right).
\end{gathered}
}
\]
\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
For the formal large-\(\mu\) extension of the isotropic \(H\)-function equation,
\[
H(0,\omega)=1\quad (0\le\omega\le 1),
\qquad
\lim_{\mu\to\infty}H(\mu,\omega)=\frac{1}{\sqrt{1-\omega}}\quad (0\le\omega<1),
\]
and the finite large-\(\mu\) value diverges as \(\omega\uparrow 1\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &0\le \omega\le 1,
\quad \mu>0.\\
\text{(P2)}\quad &H(\mu,\omega)=1+\frac{\omega\mu}{2}H(\mu,\omega)
\int_0^1\frac{H(t,\omega)}{\mu+t}\,dt.\\
\text{(P3)}\quad &\alpha_0(\omega):=\int_0^1H(t,\omega)\,dt.\\
\text{(P4)}\quad &\alpha_0(\omega)=
\begin{cases}
1, & \omega=0,\\
\dfrac{2}{\omega}\left(1-\sqrt{1-\omega}\right), & 0<\omega\le 1.
\end{cases}\\
\text{(P5)}\quad &\text{For each fixed }\omega,\text{ there is }M_\omega<\infty\text{ such that }0\le H(u,\omega)\le M_\omega\text{ for }0\le u\le 1.\\
\text{(P6)}\quad &\lim_{\mu\downarrow 0}\mu\ln\left(\frac{\mu+1}{\mu}\right)=0.\\
\text{(P7)}\quad &L(\omega):=\lim_{\mu\to\infty}H(\mu,\omega)\text{ exists for }0\le\omega<1.\\
\text{(P8)}\quad &\lim_{\mu\to\infty}\int_0^1\frac{\mu}{\mu+t}H(t,\omega)\,dt
=\int_0^1H(t,\omega)\,dt.
\end{aligned}
\]

\section*{Derivation}
First take the \(\mu\downarrow 0\) limit. The nonconstant term in (P2) is bounded as follows:
\begin{align}
0&\le \frac{\omega\mu}{2}H(\mu,\omega)\int_0^1\frac{H(t,\omega)}{\mu+t}\,dt &&\text{by (P1), (P2), and (P5)}\\
&\le \frac{\omega\mu}{2}M_\omega^2\int_0^1\frac{dt}{\mu+t} &&\text{by (P5)}\\
&=\frac{\omega\mu}{2}M_\omega^2\left[\ln(\mu+t)\right]_{t=0}^{t=1} &&\text{integrate}\\
&=\frac{\omega M_\omega^2}{2}\mu\ln\left(\frac{\mu+1}{\mu}\right) &&\text{evaluate endpoints}\\
&\longrightarrow 0. &&\text{by (P6)}
\end{align}
Therefore (P2) gives
\begin{align}
H(0,\omega)&=1. &&\text{take }\mu\downarrow 0\text{ in (P2)}
\end{align}
For the formal large-\(\mu\) limit, rewrite (P2):
\begin{align}
H(\mu,\omega)
&=1+\frac{\omega}{2}H(\mu,\omega)
\int_0^1\frac{\mu}{\mu+t}H(t,\omega)\,dt. &&\text{move }\mu\text{ into the integrand}
\end{align}
Taking \(\mu\to\infty\) for \(0\le\omega<1\),
\begin{align}
L(\omega)
&=1+\frac{\omega}{2}L(\omega)
\int_0^1H(t,\omega)\,dt &&\text{by (P7) and (P8)}\\
&=1+\frac{\omega}{2}L(\omega)\alpha_0(\omega). &&\text{by (P3)}
\end{align}
Solve for \(L(\omega)\):
\begin{align}
L(\omega)\left(1-\frac{\omega}{2}\alpha_0(\omega)\right)&=1 &&\text{collect }L(\omega)\\
L(\omega)&=\frac{1}{1-\frac{\omega}{2}\alpha_0(\omega)}. &&\text{divide by the nonzero denominator}
\end{align}
For \(\omega=0\),
\begin{align}
L(0)&=\frac{1}{1-0\cdot\alpha_0(0)/2} &&\text{substitute }\omega=0\\
&=1 &&\text{simplify}\\
&=\frac{1}{\sqrt{1-0}}. &&\text{rewrite}
\end{align}
For \(0<\omega<1\), substitute (P4):
\begin{align}
1-\frac{\omega}{2}\alpha_0(\omega)
&=1-\frac{\omega}{2}\cdot\frac{2}{\omega}\left(1-\sqrt{1-\omega}\right) &&\text{by (P4)}\\
&=1-\left(1-\sqrt{1-\omega}\right) &&\text{cancel factors}\\
&=\sqrt{1-\omega}. &&\text{simplify}
\end{align}
Hence
\begin{align}
L(\omega)&=\frac{1}{\sqrt{1-\omega}},\qquad 0\le\omega<1. &&\text{combine cases}
\end{align}
At \(\omega=1\), the finite denominator vanishes:
\begin{align}
1-\frac{1}{2}\alpha_0(1)
&=1-\frac{1}{2}\cdot 2 &&\text{by (P4)}\\
&=0, &&\text{simplify}
\end{align}
and the one-sided finite-value limit is
\begin{align}
\lim_{\omega\uparrow 1}\frac{1}{\sqrt{1-\omega}}&=+\infty. &&\text{positive denominator tends to }0
\end{align}

\section*{Final Result}
\[
\boxed{
H(0,\omega)=1\ (0\le\omega\le 1),\qquad
\lim_{\mu\to\infty}H(\mu,\omega)=\frac{1}{\sqrt{1-\omega}}\ (0\le\omega<1),\qquad
\lim_{\omega\uparrow 1}\lim_{\mu\to\infty}H(\mu,\omega)=+\infty
}
\]
\hfill$\blacksquare$
